const body = $input.item.json.body || {};
const message = (body.message || '').toLowerCase();
let intent = 'general';
if (/commande|livraison|suivi|tracking|expedi/.test(message)) intent = 'order_tracking';
else if (/retour|remboursement|annul/.test(message)) intent = 'return_refund';
else if (/stock|disponible|produit/.test(message)) intent = 'stock_inquiry';
else if (/ticket|incident|probl[eè]me/.test(message)) intent = 'create_ticket';
else if (/humain|conseiller|agent|parler/.test(message)) intent = 'human_request';
return [{ json: { ...body, intent, routedAt: new Date().toISOString() } }];
